import { createEffect, createSignal, onCleanup, onMount, type ParentComponent } from "solid-js";

import ContextManager from "#core/ui/context-manager/context-manager.js";
import { FiligreeTitle } from "#core/ui-next/components/filigree-title.jsx";
import { VSlot } from "#core/ui-next/components/slot.jsx";
import { SubsystemFrame } from "#core/ui-next/components/subsystem-frame.jsx";
import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";

import { HideMiniMapEvent } from "#base/ui/mini-map/panel-mini-map.js";

export declare interface SidebarChooserProps {
	context: string;
	id: string;
	name: string;
	title: string;
	closeButtonAudioGroup: string | undefined;

	/** Set to true when the chooser should close. */
	closing: boolean;

	/** Called when the close button is activated. */
	onClose?: () => void;
}

const SidebarChooserComponent: ParentComponent<SidebarChooserProps> = (props) => {
	const [getAnimation, setAnimation] = createSignal("animate-in-left");

	let hasPoppedContext = false;

	const onClose = () => {
		if (props.onClose) {
			props.onClose();
		}
		setAnimation("animate-out-left");
		setTimeout(() => {
			if (!hasPoppedContext) {
				hasPoppedContext = true;
				ContextManager.pop(props.context);
			}
		}, 200);
	};

	onMount(() => {
		window.dispatchEvent(new HideMiniMapEvent(true));

		createEffect(() => {
			if (props.closing) {
				onClose();
			}
		});

		onCleanup(() => {
			window.dispatchEvent(new HideMiniMapEvent(false));

			// If we haven't popped the context yet, do so now in order to avoid a lingering context.
			// This currently occurs when the user switches a view via a hotkey (bringing up the pause menu).  This bypasses the onClose() mechanism.
			if (!hasPoppedContext) {
				hasPoppedContext = true;
				ContextManager.pop(props.context);
			}
		});
	});

	return (
		<SubsystemFrame.B1
			id={props.id}
			name={props.name}
			class={`m-4 items-center ${getAnimation()}`}
			closeButtonAudio={props.closeButtonAudioGroup ? { group: props.closeButtonAudioGroup } : undefined}
			onClose={onClose}
			header={
				<FiligreeTitle
					text={props.title}
					bgGlow
				/>
			}
		>
			<VSlot class="flex flex-col flex-1">{props.children}</VSlot>
		</SubsystemFrame.B1>
	);
};

export const SidebarChooser = ComponentRegistry.register({
	name: "SidebarChooser",
	createInstance: SidebarChooserComponent,
});
